<!DOCTYPE html><html><head><title>Register - United States International University</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial;background:radial-gradient(circle at 10% 20%, rgba(10,25,49,.06) 0%, transparent 40%),linear-gradient(180deg,#f8f9ff 0%,#eef1f8 100%);min-height:100vh}.nav{background:#0a1931;color:white;padding:14px 25px;border-bottom:4px solid #d4af37}.card{background:white;max-width:480px;margin:60px auto;padding:32px;border-radius:12px;box-shadow:0 8px 25px rgba(10,25,49,.12);border-top:5px solid #d4af37}h2{color:#0a1931;border-left:4px solid #d4af37;padding-left:10px;text-transform:uppercase;font-size:14px}input{width:100%;padding:12px;margin-top:8px;border:1.5px solid #dbe2ef;border-radius:6px;background:#f8f9ff}button{width:100%;padding:13px;margin-top:18px;background:#0a1931;color:white;border:none;border-radius:6px;font-weight:800;text-transform:uppercase}</style></head><body><div class="nav"><b>UNITED STATES INTERNATIONAL UNIVERSITY - AFRICA</b></div><div class="card"><h2>Create Student Account</h2><p style="font-size:11px;color:#666;margin:10px 0 15px">School of Science and Technology - Laboratory Portal</p><form method="POST" action="register_action.php"><label style="font-size:10px;font-weight:800;color:#0a1931;text-transform:uppercase">Full Name</label><input type="text" name="name" required><label style="font-size:10px;font-weight:800;color:#0a1931;text-transform:uppercase;margin-top:12px;display:block">University Email</label><input type="email" name="email" placeholder="e.g. mike@usiu.ac.ke" required><label style="font-size:10px;font-weight:800;color:#0a1931;text-transform:uppercase;margin-top:12px;display:block">Password</label><input type="password" name="password" required><button>Create Account</button></form><p style="text-align:center;margin-top:12px;font-size:11px">Already have account? <a href="index.php" style="color:#0a1931;font-weight:700">Login</a></p></div></body></html>
